const r = $input.item.json;
const data = r.data || r;
const ts = new Date().toLocaleString('en-US', {timeZone: 'America/Denver', month: 'short', day: 'numeric', year: 'numeric'});

// Revenue & bookings
const revenue = data.revenue_week || data.commissions_week || null;
const revStr = revenue ? `\n• Revenue this week: $${Number(revenue).toLocaleString()}` : '';
const bookings = data.active_bookings || data.bookings_count || null;
const bookStr = bookings ? `\n• Active bookings: ${bookings}` : '';
const newClients = data.new_clients || data.prospects_added || 0;
const clientStr = newClients ? `\n• New prospects: ${newClients}` : '';

// Ops
const emailsSent = data.emails_sent || data.dani_emails || null;
const emailStr = emailsSent ? `\n• Client emails sent: ${emailsSent}` : '';
const dossierUpdates = data.dossier_updates || null;
const dossierStr = dossierUpdates ? `\n• Dossier updates: ${dossierUpdates}` : '';

// Key wins
const wins = data.wins || data.highlights || data.key_events || [];
let winsBlock = '';
if (wins.length) {
  winsBlock = '\n\n*Key Wins:*\n' + wins.slice(0,5).map(w => `• ${w.title || w.summary || w}`).join('\n');
}

// Actions needed
const actions = data.actions_needed || data.open_items || [];
let actionsBlock = '';
if (actions.length) {
  actionsBlock = '\n\n*Actions Needed:*\n' + actions.slice(0,5).map(a => `• ${a.title || a.action || a}`).join('\n');
}

// Full summary fallback
const summaryBlock = (data.summary || data.narrative) ? `\n\n${data.summary || data.narrative}` : '';

const statsBlock = `*Operations:*${revStr}${bookStr}${clientStr}${emailStr}${dossierStr}`;
const message = `*D2M Weekly Report — Week of ${ts}*\n\n${statsBlock}${winsBlock}${actionsBlock}${summaryBlock}`;
return [{ json: { message } }];
